import { updateAccountMenu } from "./solution";
import type { AccountMenuAction, AccountMenuState } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

const signedIn: AccountMenuState = {
  open: false,
  signedIn: true,
  email: "user@example.test",
  displayName: "User",
  destination: "/previous",
};
const toggledOpen = updateAccountMenu(signedIn, { type: "toggle" });
equal(toggledOpen, { ...signedIn, open: true }, "toggle opens a signed-in menu");
assert(toggledOpen !== signedIn, "successful toggle returns a new object");
const toggledClosed = updateAccountMenu(toggledOpen, { type: "toggle" });
equal(toggledClosed, signedIn, "toggle closes an open menu without changing other fields");
equal(signedIn, {
  open: false, signedIn: true, email: "user@example.test", displayName: "User", destination: "/previous",
}, "toggle does not mutate input");

const openState: AccountMenuState = { ...signedIn, open: true };
const profile = updateAccountMenu(openState, { type: "showProfile" });
equal(profile, { ...openState, open: false, destination: "/account" }, "showProfile closes menu and selects account destination");
assert(profile !== openState, "successful showProfile returns a new object");
assert(updateAccountMenu(signedIn, { type: "showProfile" }) === signedIn, "showProfile requires an open menu");

const signedOut = updateAccountMenu(openState, { type: "signOut" });
equal(signedOut, {
  open: false,
  signedIn: false,
  email: "",
  displayName: "",
  destination: "/signed-out",
}, "signOut clears account details and closes menu");
assert(signedOut !== openState, "successful signOut returns a new object");

const alreadyOut: AccountMenuState = {
  open: true,
  signedIn: false,
  email: "stale@example.test",
  displayName: "Stale",
  destination: null,
};
for (const action of [{ type: "toggle" }, { type: "showProfile" }, { type: "signOut" }] as AccountMenuAction[]) {
  assert(updateAccountMenu(alreadyOut, action) === alreadyOut, `${action.type} returns exact state when signed out`);
}

const emptyProfile: AccountMenuState = { open: false, signedIn: true, email: "", displayName: "", destination: null };
equal(updateAccountMenu(emptyProfile, { type: "toggle" }), { ...emptyProfile, open: true }, "empty profile strings are permitted");

